@push('scripts')<script>
(()=>{const list=document.getElementById('section-list'),fields=document.getElementById('order-fields');if(!list||!fields)return;let drag=null;let dragMoved=false;const sync=()=>{fields.innerHTML=[...list.querySelectorAll('.section-row')].map(x=>'<input type="hidden" name="section_order[]" value="'+x.dataset.key+'">').join('')};
const clearTargets=()=>list.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));
const save=()=>{sync();document.getElementById('home-builder').requestSubmit();};list.querySelectorAll('.section-row').forEach(row=>{row.addEventListener('dragstart',()=>{drag=row;dragMoved=true;row.classList.add('dragging')});row.addEventListener('dragover',e=>{e.preventDefault();row.classList.add('drop-target')});row.addEventListener('dragleave',()=>row.classList.remove('drop-target'));row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('drop-target');if(!drag||drag===row)return;const rect=row.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2)list.insertBefore(drag,row);else list.insertBefore(drag,row.nextSibling);sync()});row.addEventListener('dragend',()=>{row.classList.remove('dragging');drag=null;clearTargets();sync()});row.addEventListener('touchcancel',()=>{drag=null;dragMoved=false;clearTargets()})});sync();const refreshMoveButtons=()=>{const rows=[...list.querySelectorAll('.section-row')];rows.forEach((r,n)=>{r.querySelector('.move-up').disabled=n===0;r.querySelector('.move-down').disabled=n===rows.length-1})};list.querySelectorAll('.mobile-order button').forEach(button=>{button.addEventListener('click',()=>{const row=button.closest('.section-row'),rows=[...list.querySelectorAll('.section-row')],i=rows.indexOf(row);if(i<0)return;if(button.classList.contains('move-up')&&i>0)list.insertBefore(row,rows[i-1]);if(button.classList.contains('move-down')&&i<rows.length-1)list.insertBefore(rows[i+1],row);sync();refreshMoveButtons()})});refreshMoveButtons();document.getElementById('home-builder').addEventListener('submit',sync);document.querySelectorAll('.home-mode').forEach(select=>{const controls=select.closest('.section-controls'),panel=controls?.querySelector('.selection-panel'),limit=controls?.querySelector('.limit-control input');const boxes=()=>[...panel.querySelectorAll('input[type=checkbox]')];const refresh=()=>{if(!panel)return;const selected=boxes().filter(x=>x.checked);panel.querySelector('[data-count]').textContent=selected.length+' selected';const max=Math.max(1,Math.min(100,parseInt(limit?.value||'100',10)));boxes().forEach(x=>{x.disabled=!x.checked&&selected.length>=max})};const syncMode=()=>{if(panel)panel.hidden=select.value!=='selected';refresh()};select.addEventListener('change',syncMode);limit?.addEventListener('input',refresh);panel?.querySelector('.picker-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();panel.querySelectorAll('.picker-item').forEach(item=>{item.hidden=!!q&&!item.dataset.search.includes(q)})});panel?.addEventListener('change',e=>{if(e.target.matches('input[type=checkbox]'))refresh()});syncMode()});document.getElementById('home-builder').addEventListener('change',e=>{if(e.target.matches('input[type=checkbox]')){e.target.closest('.section-row')?.setAttribute('data-state',e.target.checked?'visible':'hidden')}})})();
</script>@endpush